const r = $input.first().json;
const status = Number(r.statusCode ?? 0);
const body = r.body ?? {};
const prep = $('Preparar Caso IRIS').first().json;

// IRIS colapsa la mayoria de errores de negocio a un mensaje generico sin
// detalle de campo (app/business/cases.py:116-118), asi que body.data no es
// fiable para explicar que fallo.
const iris_ok = status >= 200 && status < 300 &&
                body.status === 'success' &&
                Boolean(body.data?.case_id);

return [{ json: {
  ...prep,
  iris_ok,
  iris_case_id: body.data?.case_id ?? null,
  iris_soc_id: body.data?.soc_id ?? null,
  iris_status: status,
  iris_motivo: iris_ok ? '' :
    `HTTP ${status} — ${String(body.message ?? 'sin mensaje de IRIS').slice(0, 200)}`,
}}];

