parameters.jsCode:
const d = $('Code Merge Final').first().json;
const w = d.wazuh ?? {};
const c = d.cti ?? {};
const dec = d.decision ?? {};

const norm = s => String(s ?? '').trim().toUpperCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// $('Nodo').first() lanza excepcion si el nodo no llego a ejecutarse. El
// encadenamiento opcional no protege: el error se produce antes de evaluarlo.
// Misma convencion que Code Merge Final.
function salidaDe(nombre) {
  try {
    return $(nombre).first()?.json ?? {};
  } catch (e) {
    return {};
  }
}

// El roomId se resuelve aqui, una sola vez, y viaja en el item. Si se
// referenciara desde las plantillas de los nodos de Rocket.Chat, una
// ejecucion en la que 'Crear War Room' no haya corrido todavia rompe el
// nodo de aviso — justamente el que debe avisar de los fallos.
const war = salidaDe('Crear War Room');
const room_id = war.group?._id ?? war.channel?._id ?? '';

// Vocabulario cerrado en origen: fase3-agentic/app/llm.py:173 rechaza
// severidades fuera de SEVERITY_VALUES y agents.py:81-86 cae al motor
// determinista si el guardrail se dispara. Todos los caminos de triage_agent
// producen severity_real. El defecto es red de seguridad, no camino esperado.
// Tabla real de IRIS (fase6-iris/source/app/post_init.py:694-707):
// 1=Unspecified, 2=Informational, 3=Low, 4=Medium, 5=High, 6=Critical
const SEV = { CRITICA: 6, ALTA: 5, MEDIA: 4, BAJA: 3 };
const sevLabel = norm(dec.severity_real);
const severity_id = SEV[sevLabel] ?? 1;
const sev_no_reconocida = !(sevLabel in SEV);

// F14-bis: estos IDs vienen del orden de carga de una taxonomia MISP de
// terceros en el primer arranque de IRIS (post_init.py:638-660), no son
// constantes declaradas. Verificar contra la instancia antes de produccion
// real: GET /manage/case-classifications/list
const grupos = (w.rule_groups ?? []).map(g => String(g).toLowerCase());
let classification_id = 36; // other:other — defecto honesto: sin clasificar.
// Un ID especifico aqui afirma una clasificacion que no se ha determinado.
// Ampliar las ramas segun el censo de grupos; no cambiar este defecto.
if (grupos.some(g => ['authentication_failed', 'authentication_failures',
                      'sshd', 'win_authentication_failed'].includes(g))) {
  classification_id = 15; // intrusion-attempts:login-attempts
} else if (grupos.some(g => ['rootcheck', 'rootkit', 'malware'].includes(g))) {
  classification_id = 10; // malicious-code:rootkit
}

// El texto del LLM viaja influido por rule_desc/full_log, que un atacante
// controla parcialmente. Se neutraliza lo que rompe el Markdown de IRIS.
const md = (s, max = 600) => String(s ?? '')
  .replace(/[`*_~<>[\]|#]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max) || 'N/D';

const corto = md(w.rule_desc, 80);
const case_name = `[${sevLabel}] ${w.rule_id} — ${corto} · ${w.agent_name}`;

const lineas = [
  `## Incidente ${sevLabel}`,
  '',
  `| Campo | Valor |`,
  `| --- | --- |`,
  `| Regla | ${w.rule_id} (nivel Wazuh ${w.rule_level}) |`,
  `| Descripción | ${md(w.rule_desc, 200)} |`,
  `| Agente | ${md(w.agent_name, 60)} (${md(w.agent_ip, 40)}) |`,
  `| IP origen | ${md(w.src_ip, 40)} |`,
  `| Evento | ${md(w.event_timestamp, 40)} |`,
  `| Ingesta en el enclave | ${md(w.ingest_timestamp, 40)} |`,
  `| Alerta Wazuh | ${md(w.alert_id, 60)} |`,
  '',
  `## Triaje — motor ${md(dec.analysis_mode, 60)}`,
  '',
  `- Severidad: **${sevLabel}** (score ${dec.score ?? 'N/D'})`,
  `- ATT&CK: ${md(dec.mitre_technique, 80)} / ${md(dec.mitre_tactic, 80)}`,
  `  (fuente: ${md(dec.mitre_source, 40)})`,
  `- Resumen: ${md(dec.summary)}`,
  `- Recomendación: ${md(dec.recommendation)}`,
  '',
  `## Inteligencia`,
  '',
  `- AbuseIPDB: ${c.abuse_confidence ?? 0}% de confianza, ` +
    `${c.abuse_total_reports ?? 0} reportes, país ${md(c.abuse_country, 10)}` +
    `${c.abuse_is_tor ? ', **nodo Tor**' : ''}`,
  `- VirusTotal: ${c.vt_malicious ?? 0} motores maliciosos, ` +
    `${c.vt_suspicious ?? 0} sospechosos, ${c.vt_harmless ?? 0} inocuos ` +
    `(ASN ${md(c.vt_asn, 20)}, ${md(c.vt_as_owner, 60)})`,
  `- MISP: ${c.misp_total ?? 0} atributos coincidentes`,
];

if (c.enrichment_skipped) {
  lineas.push(`- ⚠ Enriquecimiento omitido: ${md(c.enrichment_skipped, 120)}`);
}

// Solo se escribe la seccion cuando hay algo que contar: una linea fija de
// "guardrail: false" en cada caso se vuelve invisible en una semana.
const avisos = [];
if (dec.guardrail_triggered) {
  avisos.push(`- 🛡 **Guardarraíl activado:** ${md(dec.guardrail_reason, 300)}`);
}
if (dec.llm_proposed_severity &&
    norm(dec.llm_proposed_severity) !== sevLabel) {
  avisos.push(`- El modelo propuso **${md(dec.llm_proposed_severity, 20)}**; ` +
              `prevalece la del motor determinista.`);
}
if (dec.degraded_reason) {
  avisos.push(`- ⚠ Triaje degradado: ${md(dec.degraded_reason, 300)}`);
}
if (sev_no_reconocida) {
  avisos.push(`- ⚠ **Severidad no reconocida:** ` +
              `\`${md(dec.severity_real, 40)}\` → Unspecified. ` +
              `Revisar el vocabulario del triaje.`);
}

if (avisos.length) {
  lineas.push('', '## Contención y anomalías', '', ...avisos);
}

lineas.push('', '---', '',
  `War Room: #${md(d.war_room_name, 60)}`,
  `Caso creado automáticamente por n8n desde el enclave OOB.`);

return [{ json: {
  ...d,
  sev_no_reconocida,
  room_id,
  iris_payload: {
    case_name,
    case_description: lineas.join('\n'),
    case_customer: 1,          // IrisInitialClient, verificado 2026-09-13
    case_soc_id: String(w.alert_id ?? ''),
    classification_id,
    severity_id,
  },
}}];

