const crypto = require('crypto');
const d = $('Evaluar Respuesta IRIS').first().json;

const case_id = d.iris_case_id;
const host = String(d.wazuh.agent_name || '').trim();

// incidentid construye la clave del objeto en MinIO y el orchestrator lo
// valida contra ^[A-Za-z0-9._-]{1,64}$. Atarlo al caso IRIS hace que la
// evidencia en MinIO y el caso sean rastreables el uno desde el otro.
const incidentid = `INC-${case_id}`;
const profile = 'generic_high_signal_collection';

const body = JSON.stringify({ incidentid, host, profile, source: 'n8n' });
const ts = Math.floor(Date.now() / 1000).toString();
const nonce = crypto.randomUUID();
const sig = crypto.createHmac('sha256', $env.ORCH_HMAC_SECRET)
  .update(`${ts}.${nonce}.` + body)
  .digest('hex');

return [{ json: { ...d, case_id, incidentid, body, ts, nonce, sig } }];

const col = $('Lanzar Recolección').first().json;
const m = col.manifest;
const prev = $('Firmar Recolección').first().json;

const iso = s => `${s.slice(0,4)}-${s.slice(4,6)}-${s.slice(6,8)}T` +
                 `${s.slice(9,11)}:${s.slice(11,13)}:${s.slice(13,15)}`;

return [{ json: {
  case_id: prev.case_id,
  zip_sha256: m.zip_sha256,
  evidencia: {
    filename: 'velociraptor_collection.zip',
    file_hash: m.zip_sha256,
    file_size: m.zip_size_bytes,
    type_id: 39,
    acquisition_date: iso(m.ended_at),
    start_date: iso(m.started_at),
    end_date: iso(m.ended_at),
    file_description:
      `Coleccion Velociraptor — flow ${m.velociraptor_flow_id}, cliente ` +
      `${m.velociraptor_client_id} (${m.velociraptor_client_os}), perfil ` +
      `${m.collection_profile}, ${m.total_collected_rows} filas. ` +
      `Objeto en ${m.zip_path}. Manifiesto y sha256.txt junto al objeto.`,
  },
}}];

const esperado = $('Preparar Evidencia').first().json.zip_sha256;
const case_id  = $('Preparar Evidencia').first().json.case_id;
const m        = $('Lanzar Recolección').first().json.manifest;
const lista    = $('Verificar Evidencia').first().json;

// /case/evidences/list devuelve { data: { evidences: [...], state: {...} } }.
// El nodo HTTP de n8n entrega el cuerpo completo, asi que se navega desde
// data. Si IRIS cambiara la forma, ev queda undefined y se detecta abajo.
const evidencias = lista?.data?.evidences ?? [];

// Un caso puede tener varias evidencias (recolecciones sucesivas del mismo
// incidente). Se busca por hash, no se toma la ultima: coger la ultima daria
// por buena una evidencia distinta si el alta hubiera fallado.
const ev = evidencias.find(e => e.file_hash === esperado);

const ok = Boolean(ev);

let motivo = '';
if (!ok) {
  if (evidencias.length === 0) {
    motivo = 'IRIS no devuelve ninguna evidencia para el caso';
  } else {
    const hashes = evidencias.map(e => e.file_hash ?? '(sin hash)');
    motivo = `ninguna de las ${evidencias.length} evidencias del caso ` +
             `casa con el hash del manifiesto. Presentes: ${hashes.join(', ')}`;
  }
}

return [{ json: {
  case_id,
  custodia_ok: ok,
  esperado,
  motivo,
  evidence_id: ev?.id ?? null,
  flow_id: m.velociraptor_flow_id,
  zip_path: m.zip_path,
